请输出 verdict、total_score、summary 以及各维度 score/comment。', CAST('{"properties":{"dimensions":{"items":{"properties":{"comment":{"type":"string"},"dimensionKey":{"enum":["RELEVANCE","ACCURACY","FORMAT","SAFETY"],"type":"string"},"score":{"type":"number"}},"required":["dimensionKey","score"],"type":"object"},"type":"array"},"summary":{"type":"string"},"total_score":{"type":"number"},"verdict":{"enum":["PASS","REJECT","REQUIRE_HUMAN"],"type":"string"}},"required":["verdict","summary","dimensions"],"type":"object"}' AS JSON), CAST('{"levels":[{"actions":["approve","reject","return"],"key":"L1","label":"初审"}]}' AS JSON), CAST('{"mode":"RATIO","value":0.2}' AS JSON), CAST('{"modelKey":"deepseek-v4-flash","providerCode":"deepseek"}' AS JSON), CAST('["seed","qa_quality","multimedia"]' AS JSON), 36, 6, 180, 4, 4.70, 12, 1, 1, 'APPROVED', 'ACTIVE', '2026-06-03 09:16:00.000');

