  (910231000001, 1, 910100000001, 910100000001, 910230000001, 910260000001, 'TPL_PREF_COMPARE_V1', '偏好对比标注模板', 'PREFERENCE_COMPARE', '基于 preference_compare 数据集的偏好对比标注模板。', 910232000002, 3, 'PUBLISHED'),
  (910231000002, 1, 910100000001, 910100000001, 910230000012, NULL, 'TPL_HEALTH_SPARSE', '偏好对比 · 未聚合演示', 'PREFERENCE_COMPARE', '偏好对比 · 未聚合演示', 910232000004, 1, 'PUBLISHED'),
