INSERT INTO `template_versions` (
  `id`, `tenant_id`, `created_by`, `updated_by`, `task_id`, `template_id`, `version_no`, `template_name`, `status`, `is_current`, `schema_json`, `schema_checksum`, `review_prompt_template`, `review_output_schema_json`, `review_workflow_json`, `acceptance_rule_json`, `llm_assist_config_json`, `provider_platform_key`, `model_id`, `widget_count`, `required_field_count`, `validation_errors_json`, `published_at`, `archived_at`, `archived_reason`
) VALUES
  (910232000001, 1, 910100000001, 910100000001, 910230000001, 910231000001, 1, '偏好对比标注模板 v1', 'ARCHIVED', 0, CAST('{"actions":[{"key":"saveDraft","kind":"secondary","label":"保存草稿"},{"key":"submit","kind":"submit","label":"提交"}],"description":"对同一 prompt 下的两个回答进行偏好判断，用于奖励模型训练与对齐。","sections":[{"description":"先阅读规则，再进行偏好判断。","fields":[{"component":"showItem","key":"__instructions","label":"标注说明","meta":{"importRole":"runtime","payloadSource":"runtime"},"path":"__instructions","readonly":true,"showItem":{"contentSource":"static","layout":"pre","renderAs":"markdown","staticContent":"# 标注要求 · 偏好对比标注（preference_compare）\\n\\n## 任务背景\\n\\n本数据集为「偏好对比标注（Pairwise Preference）」题目。每条给出同一 **prompt** 下两个模型回答 **A** 与 **B**，标注员需判断 **哪个更好** 并说明依据，用于奖励模型训练与对齐评估。\\n\\n## 字段说明\\n\\n| 字段 | 含义 | 是否参与标注 |\\n|------|------|-------------|\\n| `id` | 题目唯一编号（P0001–P0036） | 否（展示） |\\n| `task_type` | 任务类型 | 否（展示） |\\n| `lang` | 语言 | 否 |\\n| `prompt` | 用户问题或指令 | 否（阅读） |\\n| `response_a` / `response_b` | 两个候选回答 | 否（阅读） |\\n| `model_a` / `model_b` | 模型标识 | 否（展示） |\\n| `preferred` | 偏好结论：A / B / tie | **是** |\\n| `margin` | 优势程度：明显优于 / 略优于 / 相当 | **是** |\\n| `dimensions` | 判断维度（多选） | **是** |\\n| `safety_flag` | 是否存在安全风险 | **是** |\\n| `annotator_note` | 判断理由 | **是** |\\n| `difficulty` | 难度标签 | 否（参考） |\\n| `tags` | 主题标签 | 否（参考） |\\n\\n## 标注原则\\n\\n1. **准确性优先**：事实错误、计算错误、违规内容应优先影响偏好。\\n2. **安全合规**：涉及隐私、危险行为、骚扰等，应偏好拒答或合规引导，并勾选 `safety_flag`。\\n3. **边界题**：`task_type=边界/平局` 或两答案接近时，可选 `tie` 与 `相当`。\\n4. **理由具体**：`annotator_note` 需引用题面差异，避免空泛套话。\\n\\n## 维度参考\\n\\n常用维度：准确性、完整性、相关性、可读性、安全性、合规性、可执行性、上下文一致、创意性、感染力、简洁性等。按题意选择 1–3 项即可。"},"span":24,"value_type":"string"}],"key":"instructions","title":"标注说明"},{"description":"以下信息只读展示，不直接提交。","fields":[{"component":"showItem","key":"sampleId","label":"样本ID","path":"sample_id","readonly":true,"showItem":{"contentSource":"payload","layout":"inline","renderAs":"text"},"span":12,"value_type":"string"},{"component":"showItem","key":"taskType","label":"任务类型","path":"task