INSERT INTO `ai_review_misalignment_cases` (
  `id`, `tenant_id`, `created_by`, `updated_by`, `template_version_id`, `task_id`, `submission_id`, `submission_version_id`, `ai_review_id`, `ai_verdict`, `human_label`, `misalignment_type`, `appeal_id`, `item_payload_json`, `submit_data_json`, `ai_summary_text`, `ai_dimension_scores_json`, `human_comment_text`, `split_tag`
) VALUES
  (910271000001, 1, 0, 0, 910232000002, 910230000001, 910238000001, 910239000001, 910243000001, 'REJECT', 'PASS', 'AI_STRICT', NULL, CAST('{"lang":"zh","model_a":"deepseek-v4-flash","model_b":"deepseek-reasoner","prompt":"什么是机器学习？请用简洁语言解释。","response_a":"机器学习是让计算机从数据中自动学习规律，而无需为每个任务手写全部规则的技术。常见做法包括监督学习、无监督学习和强化学习。","response_b":"机器学习就是 AI，让电脑变聪明。","sample_id":"P0001","task_type":"知识问答"}' AS JSON), CAST('{"result":{"annotator_note":"A 给出定义并补充学习方式，B 过于笼统。","dimensions":["准确性","完整性"],"evidence_files":[{"fileId":910220000003,"mimeType":"image/png","name":"evidence-910220000003.png","sizeBytes":20480}],"margin":"明显优于","preferred":"A","quick_conclusion":"A 在 准确性,完整性 上更优。","rewrite_suggestion":"<p>建议保留更优回答的核心表达，并进一步补充风险提示或更明确的步骤。</p><blockquote>机器学习是让计算机从数据中自动学习规律，而无需为每个任务手写全部规则的技术。常见做法包括监督学习、无监督学习和强化学习。</blockquote>","safety_flag":false,"structured_annotation":{"dimensions":["准确性","完整性"],"margin":"明显优于","note":"A 给出定义并补充学习方式，B 过于笼统。","safetyFlag":false,"winner":"A"}},"runtime":{"ai_reference":"AI 认为 A 更优，建议重点检查 准确性, 完整性。"}}' AS JSON), 'AI 以「准确性不足」驳回；人工仍选 A （明显优于），认为差异不足以否决整条标注。', CAST('[{"comment":"答案是否准确命中需求。","dimensionKey":"ACCURACY","score":95},{"comment":"是否覆盖关键点。","dimensionKey":"COMPLETENESS","score":95},{"comment":"是否直接回应问题。","dimensionKey":"RELEVANCE","score":95},{"comment":"语言是否清晰简洁。","dimensionKey":"READABILITY","score":95},{"comment":"是否存在违规或风险表达。","dimensionKey":"SAFETY","score":95}]' AS JSON), '申诉成立：A 在准确性、完整性上略优，AI 不应因措辞冗余否定有效判断。', 'TRAIN'),
  (910271000002, 1, 0, 0, 910232000002, 910230000001, 910238000002, 910239000002, 910243000002, 'REJECT', 'PASS', 'AI_STRICT', NULL, CAST('{"lang":"zh","model_a":"deepseek-v4-flash","model_b":"deepseek-reasoner","prompt":"北京故宫始建于哪个朝代？","response_a":"北京故宫始建于明朝永乐年间，1406 年动工，1420 年基本建成，是明清两代皇宫。","response_b":"故宫建于明朝，具体年份说法不一，一般认为是 15 世纪初由永乐帝主持营建，属于明清皇宫。","sample_id":"P0002","task_type":"知识问答"}' AS JSON), CAST('{"result":{"annotator_note":"A 时间更精确；B 正确但表述偏模糊，退回后仍可接受。","dimensions":["准确性","完整性"],"evidence_files":[],"margin":"略优于","preferred":"A","quick_conclusion":"A 在 准确性,完整性 上更优。","rewrite_suggestion":"<p>建议保留更优回答的核心表达，并进一步补充风险提示或更明确的步骤。</p><blockquote>北京故宫始建于明朝永乐年间，1406 年动工，1420 年基本建成，是明清两代皇宫。</blockquote>","safety_flag":false,"structured_annotation":{"dimensions":["准确性","完整性"],"margin":"略优于","note":"A 时间更精确；B 正确但表述偏模糊，退回后仍可接受。","safetyFlag":false,"winner":"A"}},"runtime":{"ai_reference":"AI 认为 A 更优，建议重点检查 准确性, 完整性。"}}' AS JSON), 'AI 以「准确性不足」驳回；人工仍选 A （略优于），认为差异不足以否决整条标注。', CAST('[{"comment":"答案是否准确命中需求。","dimensionKey":"ACCURACY","score":95},{"comment":"是否覆盖关键点。","dimensionKey":"COMPLETENESS","score":95},{"comment":"是否直接回应问题。","dimensionKey":"RELEVANCE","score":95},{"comment":"语言是否清晰简洁。","dimensionKey":"READABILITY","score":95},{"comment":"是否存在违规或风险表达。","dimensionKey":"SAFETY","score":95}]' AS JSON), '申诉成立：A 在准确性、完整性上略优，AI 不应因措辞冗余否定有效判断。', 'TRAIN'),
  (910271000003, 1, 0, 0, 910232000002, 910230000001, 910238000002, 910239000003, 910243000003, 'PASS', 'REJECT', 'AI_LENIENT', NULL, CAST('{"lang":"zh","model_a":"deepseek-v4-flash","model_b":"deepseek-reasoner","prompt":"人体最大的器官是什么？","response_a":"人体最大的器官是肝脏，因为它负责解毒和代谢。","response_b":"人体最大的器官是皮肤，它覆盖全身并承担保护、感知和调节体温等功能。","sample_id":"P0004","task_type":"知识问答"}' AS JSON), CAST('{"result":{"annotator_note":"A 时间更精确；B 正确但表述偏模糊，退回后仍可接受。","dimensions":["准确性","完整性"],"evidence_files":[],"margin":"略优于","preferred":"A","quick_conclusion":"A 在 准确性,完整性 上更优。","rewrite_suggestion":"<p>建议保留更优回答的核心表达，并进一步补充风险提示或更明确的步骤。</p><blockquote>北京故宫始建于明朝永乐年间，1406 年动工，1420 年基本建成，是明清两代皇宫。</blockquote>","safety_flag":false,"structured_annotation":{"dimensions":["准确性","完整性"],"margin":"略优于","note":"A 时间更精确；B 正确但表述偏模糊，退回后仍可接受。","safetyFlag":false,"winner":"A"}},"runtime":{"ai_reference":"AI 认为 A 更优，建议重点检查 准确性, 完整性。"}}' AS JSON), 'AI 放行标注（倾向 B），但未识别 A 侧关键缺陷。', CAST('[{"comment":"答案是否准确命中需求。","dimensionKey":"ACCURACY","score":95},{"comment":"是否覆盖关键点。","dimensionKey":"COMPLETENESS","score":95},{"comment":"是否直接回应问题。","dimensionKey":"RELEVANCE","score":95},{"comment":"语言是否清晰简洁。","dimensionKey":"READABILITY","score":95},{"comment":"是否存在违规或风险表达。","dimensionKey":"SAFETY","score":95}]' AS JSON), '人工发现事实或合规问题：题面「人体最大的器官是什么？…」中 A 回答「人体最大的器官是肝脏，因为它负责解毒和代谢。…」存在错误，AI 过松不应 PASS。', 'TRAIN'),
