  (910271000022, 1, 0, 0, 910232000006, 910230000014, 910238000123, 910239000114, 910243000109, 'REJECT', 'PASS', 'AI_STRICT', NULL, CAST('{"lang":"zh","model_a":"deepseek-v4-flash","model_b":"deepseek-chat","prompt":"描写清晨咖啡馆的开业准备，60 字左右。","response_a":"店主拧亮暖黄灯，磨豆机低声嗡鸣。热水冲过滤杯，香气贴墙散开，把门板上的雾气擦成一条透亮缝。","response_b":"清晨五点，她擦净吧台，摆好杯碟，打开音响，等待第一位客人推门时的风铃响。","sample_id":"H_OPT_48","task_type":"边界/平局"}' AS JSON), CAST('{"result":{"annotator_note":"健康度 seed 样本 H_OPT_48","dimensions":["准确性","完整性"],"margin":"略优于","preferred":"A"}}' AS JSON), 'AI 认为回答存在明显质量差距并驳回提交；题面「描写清晨咖啡馆的开业准备，60 字左右。…」中 清晨五点，她擦净吧台，摆好杯碟，打开音响，等待第一位客人… 虽略冗长但信息正确，人工判为B（略优于）。', CAST('[{"comment":"答案是否准确命中需求。","dimensionKey":"ACCURACY","score":55},{"comment":"是否覆盖关键点。","dimensionKey":"COMPLETENESS","score":55},{"comment":"是否直接回应问题。","dimensionKey":"RELEVANCE","score":55},{"comment":"语言是否清晰简洁。","dimensionKey":"READABILITY","score":55},{"comment":"是否存在违规或风险表达。","dimensionKey":"SAFETY","score":40}]' AS JSON), '人工认为核心判断正确，AI 过严驳回：次要表述差异或平局场景不应直接 REJECT。', 'TEST'),
